window.MG_LAZY_DATA["data/lazy/owner-courses/b316-ab86f73c210ad312.json"]={sha256:"ab86f73c210ad312cdd8d456fbb0b86e1cec67f8ff21e7bf3ca80f787f668964",value:{"id":"b316","title":"青藏鐵路凍土地段","titleEn":"Qinghai–Tibet Railway permafrost sections","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"以青藏鐵路凍土地段為背景，建立路基熱量、地下冰與列車荷載共同作用的教學剖面。學徒必須分開季節凍融和長期溫度趨勢，將溫度、沉陷與排水量同步量測，並辨認縮尺熱模型不能直接預測真實凍土穩定年限。","summaryEn":"Use the permafrost sections of the Qinghai–Tibet Railway to construct a teaching profile combining ground heat, ice and train loading. Separate seasonal freeze-thaw from long-term temperature trends. Measure temperature, settlement and drainage together, and identify why a scaled thermal model cannot directly predict the actual service life or stability of frozen ground.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、軌道進入、牽引供電隔離或列車營運許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, track-access, traction-power isolation or train-operation permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"rail-track","subcategoryTitle":"軌道與土建工程","subcategoryTitleEn":"Track and civil engineering","learningTrack":"rail","learningSubdiscipline":"rail-track","learningTags":["rail","rail-track","track"],"architectureFamily":"rail-system","architectureNodes":[["路線與土建","Alignment and civil works"],["車輛與接觸","Vehicle and contact"],["牽引供電","Traction supply"],["行車控制","Movement control"],["車站與旅客","Stations and passengers"],["監測與維護","Monitoring and maintenance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[3,4],[4,5],[5,0],[5,3]],"diagram":{"type":"rail-system","labels":["路線與土建","車輛與接觸","牽引供電","行車控制","車站與旅客"],"labelsEn":["Alignment and civil works","Vehicle and contact","Traction supply","Movement control","Stations and passengers"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合原創算例：單元 1 得 thaw_depth=0.1130625 m；單元 2 得 gradient=0.606 mm/m；單元 3 得 flow=0.30906 m^3/s。上述三個結果使用各單元明示的不同邊界，不能任意相加或視為實際工程實測值。以第一單元 heat 的擾動測試，結果改為 0.1243688 m；學徒需先比較單位、敏感度和假設，再決定是否要細化模型。以青藏鐵路凍土地段為背景，建立路基熱量、地下冰與列車荷載共同作用的教學剖面。學徒必須分開季節凍融和長期溫度趨勢，將溫度、沉陷與排水量同步量測，並辨認縮尺熱模型不能直接預測真實凍土穩定年限。 最終交付應保留原始輸入、測點時間戳、誤差範圍與無法由簡化式證明的結論。","textEn":"Integrated original exercise: unit 1 gives thaw_depth=0.1130625 m; unit 2 gives gradient=0.606 mm/m; unit 3 gives flow=0.30906 m^3/s. These three results use different explicit boundaries and must not be added or presented as measurements of the real railway. Perturbing heat in the first unit changes its result to 0.1243688 m. Compare units, sensitivity and assumptions before deciding which model needs refinement. Use the permafrost sections of the Qinghai–Tibet Railway to construct a teaching profile combining ground heat, ice and train loading. Separate seasonal freeze-thaw from long-term temperature trends. Measure temperature, settlement and drainage together, and identify why a scaled thermal model cannot directly predict the actual service life or stability of frozen ground. The final submission should retain original inputs, measurement timestamps, uncertainty ranges and conclusions that the simplified expressions cannot establish.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":16,"enrichmentVersion":16,"stages":[{"id":"b316-v16-s1","title":"凍土潛熱與融化厚度與沉陷差與軌道坡折","titleEn":"Permafrost latent heat and thaw depth & Differential settlement and track kink","description":"本階段聚焦「凍土潛熱與融化厚度」與「沉陷差與軌道坡折」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Permafrost latent heat and thaw depth\" and \"Differential settlement and track kink\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b316-v16-01","title":"凍土潛熱與融化厚度：機制與系統路徑","titleEn":"Permafrost latent heat and thaw depth: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":[],"objective":"說明「凍土潛熱與融化厚度」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Permafrost latent heat and thaw depth” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"凍土融化需要供應冰的潛熱，單位面積熱量除以體積潛熱可估算理想融化厚度。實際土層含水率、對流與季節反覆凍融會改變結果，融化厚度也不直接等於路基沉陷。 熱量除以單位體積融冰潛熱給出等效融化深度，模型只做能量帳。它沒有求解隨時間移動的凍融前緣，也未計土體顯熱、地下水輸熱與表面散熱，因此不能直接預測凍土壽命。 將輸入熱量與單位體積融冰潛熱需求分開，辨認等效融化深度不等同沉陷量。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「凍土潛熱與融化厚度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Thawing ground requires the latent heat of its ice. Heat input per area divided by volumetric latent heat gives an ideal thaw depth. Water content, convection and repeated seasonal freezing modify the result, and thaw depth is not identical to embankment settlement. Heat divided by latent melting energy per unit volume gives an equivalent thaw depth. This is an energy account, not a solution for a time-dependent thaw front. Soil sensible heat, groundwater transport and surface losses remain excluded, so it cannot directly predict permafrost life. Separate incoming heat from volumetric latent melting demand and distinguish equivalent thaw depth from settlement. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Permafrost latent heat and thaw depth” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1；計算：thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1; calculation: thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m.","failure":"常見誤解：「計算出的凍土融化厚度必定等於路基沉陷量」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Calculated permafrost thaw depth necessarily equals embankment settlement.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「凍土潛熱與融化厚度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Permafrost latent heat and thaw depth”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-01-k1","title":"凍土潛熱與融化厚度","titleEn":"Permafrost latent heat and thaw depth","text":"凍土融化需要供應冰的潛熱，單位面積熱量除以體積潛熱可估算理想融化厚度。實際土層含水率、對流與季節反覆凍融會改變結果，融化厚度也不直接等於路基沉陷。","textEn":"Thawing ground requires the latent heat of its ice. Heat input per area divided by volumetric latent heat gives an ideal thaw depth.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：計算出的凍土融化厚度必定等於路基沉陷量 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Calculated permafrost thaw depth necessarily equals embankment settlement. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「凍土潛熱與融化厚度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Permafrost latent heat and thaw depth\" is correct?","options":["計算出的凍土融化厚度必定等於路基沉陷量","凍土融化需要供應冰的潛熱，單位面積熱量除以體積潛熱可估算理想融化厚度。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Calculated permafrost thaw depth necessarily equals embankment settlement.","Thawing ground requires the latent heat of its ice.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"凍土融化需要供應冰的潛熱，單位面積熱量除以體積潛熱可估算理想融化厚度。 其餘選項是常見誤解。","explanationEn":"Thawing ground requires the latent heat of its ice. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b316-v16-02","title":"凍土潛熱與融化厚度：定量估算","titleEn":"Permafrost latent heat and thaw depth: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-01"],"objective":"以數值模型估算「凍土潛熱與融化厚度」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Permafrost latent heat and thaw depth” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1；計算：thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m。敏感度：heat 單獨增加百分之十至 1.3332e+07 J/m^2，其餘固定，結果為 0.1243688 m。模型邊界：全部熱量用於相變且冰分率均勻；不計顯熱、地下水及土骨架壓縮。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1; calculation: thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m. Sensitivity: heat, increase this input alone by ten percent, to 1.3332e+07 J/m^2, with all other inputs fixed, gives 0.1243688 m. Model boundary: All input heat goes to phase change with uniform ice fraction; sensible heat, groundwater and skeleton compression are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將溫度剖面、含冰量和路基高程聯合判讀，固定測點深度基準，避免把感測器隨沉陷移動誤當成融化面下移。","observationEn":"How to cross-check: Interpret temperature profiles, ice content and elevation together, maintain a fixed depth datum, and avoid mistaking sensor movement with settlement for a descending thaw front.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1；計算：thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m。敏感度：heat 單獨增加百分之十至 1.3332e+07 J/m^2，其餘固定，結果為 0.1243688 m。模型邊界：全部熱量用於相變且冰分率均勻；不計顯熱、地下水及土骨架壓縮。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1; calculation: thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m. Sensitivity: heat, increase this input alone by ten percent, to 1.3332e+07 J/m^2, with all other inputs fixed, gives 0.1243688 m. Model boundary: All input heat goes to phase change with uniform ice fraction; sensible heat, groundwater and skeleton compression are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「凍土潛熱與融化厚度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Permafrost latent heat and thaw depth\", which statement holds?","options":["完全拘束的鋼軌升溫仍會無應力地自由伸長","空氣體積流率相同就表示任何海拔的散熱質量流率相同","原創假想算例，全部輸入均非本工程操作參數：heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1。"],"optionsEn":["A fully restrained rail still expands freely without stress when heated.","Equal volumetric airflow guarantees equal cooling mass flow at every altitude.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1；計算：thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=1.212e+07 J/m^2; ice_density=917 kg/m^3; latent=334000 J/kg; ice_fraction=0.35 1; calculation: thaw_depth=heat/(ice_density*latent*ice_fraction)=0.1130625 m. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b316-v16-03","title":"凍土潛熱與融化厚度：試驗與驗證","titleEn":"Permafrost latent heat and thaw depth: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「凍土潛熱與融化厚度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Permafrost latent heat and thaw depth” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將溫度剖面、含冰量和路基高程聯合判讀，固定測點深度基準，避免把感測器隨沉陷移動誤當成融化面下移。 用不同深度溫度鏈與土壤含冰量取樣核對輸入，另以實測融深檢查能量帳缺少的項目。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Interpret temperature profiles, ice content and elevation together, maintain a fixed depth datum, and avoid mistaking sensor movement with settlement for a descending thaw front. Check inputs using temperature strings and ice-content samples, then compare measured thaw depth to identify terms absent from the energy account. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對兩種含冰率計算理想融化厚度，保持熱量不變，再說明為何需要土骨架壓縮性和排水條件才能推估沉陷。 再以本單元 heat 的對照值重算 thaw_depth，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate ideal thaw depth for two ice fractions at equal heat input, then explain why skeleton compressibility and drainage are required to estimate settlement. Also recalculate thaw_depth for the alternative heat value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：局部富冰層融化可能造成不均勻沉陷，平均地溫穩定也不能排除某一薄層已跨過相變區。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Thawing an ice-rich lens can cause differential settlement, and a stable average ground temperature does not rule out phase change in a thin layer. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"將溫度剖面、含冰量和路基高程聯合判讀，固定測點深度基準，避免把感測器隨沉陷移動誤當成融化面下移。 用不同深度溫度鏈與土壤含冰量取樣核對輸入，另以實測融深檢查能量帳缺少的項目。","textEn":"Interpret temperature profiles, ice content and elevation together, maintain a fixed depth datum, and avoid mistaking sensor movement with settlement for a descending thaw front. Check inputs using temperature strings and ice-content samples, then compare measured thaw depth to identify terms absent from the energy account.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"對兩種含冰率計算理想融化厚度，保持熱量不變，再說明為何需要土骨架壓縮性和排水條件才能推估沉陷。 再以本單元 heat 的對照值重算 thaw_depth，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate ideal thaw depth for two ice fractions at equal heat input, then explain why skeleton compressibility and drainage are required to estimate settlement. Also recalculate thaw_depth for the alternative heat value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「凍土潛熱與融化厚度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Permafrost latent heat and thaw depth\"?","options":["將溫度剖面、含冰量和路基高程聯合判讀，固定測點深度基準，避免把感測器隨沉陷移動誤當成融化面下移。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","電機額定扭矩夠大就不需要考慮輪軌黏著"],"optionsEn":["Interpret temperature profiles, ice content and elevation together, maintain a fixed depth datum, and avoid mistaking sensor movement with settlement for a descending thaw front.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion."],"answer":0,"explanation":"將溫度剖面、含冰量和路基高程聯合判讀，固定測點深度基準，避免把感測器隨沉陷移動誤當成融化面下移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Interpret temperature profiles, ice content and elevation together, maintain a fixed depth datum, and avoid mistaking sensor movement with settlement for a descending thaw front. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b316-v16-04","title":"凍土潛熱與融化厚度：失效診斷","titleEn":"Permafrost latent heat and thaw depth: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-03"],"objective":"從症狀倒推「凍土潛熱與融化厚度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Permafrost latent heat and thaw depth” and propose discriminating checks, corrective actions and prevention.","instruction":"局部富冰層融化可能造成不均勻沉陷，平均地溫穩定也不能排除某一薄層已跨過相變區。 冰量分率錯估會直接改變融深，須查取樣空間代表性。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Thawing an ice-rich lens can cause differential settlement, and a stable average ground temperature does not rule out phase change in a thin layer. An incorrect ice fraction directly changes thaw depth; inspect the spatial representativeness of samples. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將輸入熱量與單位體積融冰潛熱需求分開，辨認等效融化深度不等同沉陷量。","observationEn":"Link to the mechanism: Separate incoming heat from volumetric latent melting demand and distinguish equivalent thaw depth from settlement.","failure":"誤判風險：若相信「計算出的凍土融化厚度必定等於路基沉陷量」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Calculated permafrost thaw depth necessarily equals embankment settlement.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"局部富冰層融化可能造成不均勻沉陷，平均地溫穩定也不能排除某一薄層已跨過相變區。 冰量分率錯估會直接改變融深，須查取樣空間代表性。","textEn":"Thawing an ice-rich lens can cause differential settlement, and a stable average ground temperature does not rule out phase change in a thin layer. An incorrect ice fraction directly changes thaw depth; inspect the spatial representativeness of samples.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「凍土潛熱與融化厚度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Permafrost latent heat and thaw depth\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","局部富冰層融化可能造成不均勻沉陷，平均地溫穩定也不能排除某一薄層已跨過相變區。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Thawing an ice-rich lens can cause differential settlement, and a stable average ground temperature does not rule out phase change in a thin layer.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"局部富冰層融化可能造成不均勻沉陷，平均地溫穩定也不能排除某一薄層已跨過相變區。 需以量測區分可能原因。","explanationEn":"Thawing an ice-rich lens can cause differential settlement, and a stable average ground temperature does not rule out phase change in a thin layer. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b316-v16-05","title":"沉陷差與軌道坡折：機制與系統路徑","titleEn":"Differential settlement and track kink: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-04"],"objective":"說明「沉陷差與軌道坡折」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Differential settlement and track kink” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。 相同端點坡度可以對應完全不同的中間形狀，因此坡度不能單獨表示軌道曲率。測點間距必須小於欲辨認的變形尺度，並將高程誤差相對於基長傳遞到坡度結果。 比較相鄰路基段的差異沉陷，避免只看整段平均下沉。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「沉陷差與軌道坡折」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak. A spatial profile is needed to identify curvature and deformation length. Identical endpoint gradient can hide very different intermediate shapes, so gradient alone cannot describe track curvature. Survey spacing must resolve the deformation length scale, and elevation uncertainty must be propagated relative to the baseline into the reported gradient. Compare differential settlement in neighbouring embankment sections instead of only average subsidence. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Differential settlement and track kink” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：drop=0.01212 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.606 mm/m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.01212 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.606 mm/m.","failure":"常見誤解：「兩端高程相同就能證明兩點之間沒有差異沉陷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal endpoint elevations prove there is no differential settlement between them.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「沉陷差與軌道坡折」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Differential settlement and track kink”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-05-k1","title":"沉陷差與軌道坡折","titleEn":"Differential settlement and track kink","text":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。","textEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩端高程相同就能證明兩點之間沒有差異沉陷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal endpoint elevations prove there is no differential settlement between them. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「沉陷差與軌道坡折」，下列哪一項敘述正確？","questionEn":"Which statement about \"Differential settlement and track kink\" is correct?","options":["兩端高程相同就能證明兩點之間沒有差異沉陷","排水管截面夠大就不需要檢查入口堵塞及下游水位","均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。"],"optionsEn":["Equal endpoint elevations prove there is no differential settlement between them.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading."],"answer":2,"explanation":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。 其餘選項是常見誤解。","explanationEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b316-v16-06","title":"沉陷差與軌道坡折：定量估算","titleEn":"Differential settlement and track kink: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-05"],"objective":"以數值模型估算「沉陷差與軌道坡折」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Differential settlement and track kink” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：drop=0.01212 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.606 mm/m。敏感度：drop 單獨增加百分之十至 0.013332 m，其餘固定，結果為 0.6666 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.01212 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.606 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.013332 m, with all other inputs fixed, gives 0.6666 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。","observationEn":"How to cross-check: Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：drop=0.01212 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.606 mm/m。敏感度：drop 單獨增加百分之十至 0.013332 m，其餘固定，結果為 0.6666 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.01212 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.606 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.013332 m, with all other inputs fixed, gives 0.6666 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「沉陷差與軌道坡折」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Differential settlement and track kink\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：drop=0.01212 m; baseline=20 m。","兩台儀器量得同樣座標就證明座標絕對正確","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Original hypothetical exercise.","Matching coordinates from two instruments prove absolute coordinate accuracy.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：drop=0.01212 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.606 mm/m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.01212 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.606 mm/m. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b316-v16-07","title":"沉陷差與軌道坡折：試驗與驗證","titleEn":"Differential settlement and track kink: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「沉陷差與軌道坡折」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Differential settlement and track kink” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。","textEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「沉陷差與軌道坡折」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Differential settlement and track kink\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。","量測車速度提高時仍可永遠沿用原本取樣率"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift.","The original sampling rate remains sufficient at every increased inspection speed."],"answer":1,"explanation":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b316-v16-08","title":"沉陷差與軌道坡折：失效診斷","titleEn":"Differential settlement and track kink: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-07"],"objective":"從症狀倒推「沉陷差與軌道坡折」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Differential settlement and track kink” and propose discriminating checks, corrective actions and prevention.","instruction":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較相鄰路基段的差異沉陷，避免只看整段平均下沉。","observationEn":"Link to the mechanism: Compare differential settlement in neighbouring embankment sections instead of only average subsidence.","failure":"誤判風險：若相信「兩端高程相同就能證明兩點之間沒有差異沉陷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal endpoint elevations prove there is no differential settlement between them.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。","textEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「沉陷差與軌道坡折」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Differential settlement and track kink\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","排水管截面夠大就不需要檢查入口堵塞及下游水位","基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact."],"answer":2,"explanation":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 需以量測區分可能原因。","explanationEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b316-v16-s2","title":"集水與排水容量與長軌溫升與受限熱應力","titleEn":"Catchment inflow and drainage capacity & Long-rail temperature and restrained stress","description":"本階段聚焦「集水與排水容量」與「長軌溫升與受限熱應力」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Catchment inflow and drainage capacity\" and \"Long-rail temperature and restrained stress\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b316-v16-09","title":"集水與排水容量：機制與系統路徑","titleEn":"Catchment inflow and drainage capacity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-08"],"objective":"說明「集水與排水容量」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Catchment inflow and drainage capacity” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。鐵路集水範圍若只算軌道面，會漏掉坡面與站區流入。 合理化流量法假定雨強與集流條件相符，面積及逕流係數也須明確。它估算峰值流率而非完整洪水歷線；抽水或蓄水設計還需對時間積分和出口條件。 檢查融雪水與排水溝通暢度如何改變路基附近的入流水量。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「集水與排水容量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. Actual drainage also depends on inlet blockage, pipe slope and downstream water level. Counting only track surface can omit inflow from adjacent slopes and station areas. The rational estimate assumes rainfall intensity compatible with catchment response and explicit area and runoff coefficient. It gives a peak rate, not a complete hydrograph. Pumping or storage design additionally requires time integration and outlet conditions. Check how snowmelt and drain obstruction change water inflow beside the embankment. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Catchment inflow and drainage capacity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.30906 m^3/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.30906 m^3/s.","failure":"常見誤解：「排水管截面夠大就不需要檢查入口堵塞及下游水位」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A sufficiently large drain eliminates the need to check blocked inlets and tailwater.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「集水與排水容量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Catchment inflow and drainage capacity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-09-k1","title":"集水與排水容量","titleEn":"Catchment inflow and drainage capacity","text":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。鐵路集水範圍若只算軌道面，會漏掉坡面與站區流入。","textEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. Actual drainage also depends on inlet blockage, pipe slope and downstream water level.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：排水管截面夠大就不需要檢查入口堵塞及下游水位 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A sufficiently large drain eliminates the need to check blocked inlets and tailwater. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「集水與排水容量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Catchment inflow and drainage capacity\" is correct?","options":["短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。","排水管截面夠大就不需要檢查入口堵塞及下游水位","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。 其餘選項是常見誤解。","explanationEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b316-v16-10","title":"集水與排水容量：定量估算","titleEn":"Catchment inflow and drainage capacity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-09"],"objective":"以數值模型估算「集水與排水容量」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Catchment inflow and drainage capacity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.30906 m^3/s。敏感度：rain 單獨增加百分之十至 2.222e-05 m/s，其餘固定，結果為 0.339966 m^3/s。模型邊界：均勻降雨的合理化法概念；不含集流時間、水文頻率分析或蓄滯。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.30906 m^3/s. Sensitivity: rain, increase this input alone by ten percent, to 2.222e-05 m/s, with all other inputs fixed, gives 0.339966 m^3/s. Model boundary: Uniform-rainfall rational-method concept; concentration time, frequency analysis and storage are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。","observationEn":"How to cross-check: Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.30906 m^3/s。敏感度：rain 單獨增加百分之十至 2.222e-05 m/s，其餘固定，結果為 0.339966 m^3/s。模型邊界：均勻降雨的合理化法概念；不含集流時間、水文頻率分析或蓄滯。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.30906 m^3/s. Sensitivity: rain, increase this input alone by ten percent, to 2.222e-05 m/s, with all other inputs fixed, gives 0.339966 m^3/s. Model boundary: Uniform-rainfall rational-method concept; concentration time, frequency analysis and storage are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「集水與排水容量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Catchment inflow and drainage capacity\", which statement holds?","options":["空氣體積流率相同就表示任何海拔的散熱質量流率相同","原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2。","電機額定扭矩夠大就不需要考慮輪軌黏著"],"optionsEn":["Equal volumetric airflow guarantees equal cooling mass flow at every altitude.","Original hypothetical exercise.","A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.30906 m^3/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.02e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.30906 m^3/s. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b316-v16-11","title":"集水與排水容量：試驗與驗證","titleEn":"Catchment inflow and drainage capacity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「集水與排水容量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Catchment inflow and drainage capacity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 核對雨量單位和有效集水邊界，量測泵浦出流與集水井水位變化，以體積守恆互證。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verify rainfall units and catchment boundaries, measure pump outflow and sump-level change, and cross-check them through volume conservation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將部分入口視為堵塞，建立地表暫存與排出的水量表；比較增加入口和增加泵量對不同瓶頸的效果。 再以本單元 rain 的對照值重算 flow，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Block selected inlets in the scenario, tabulate surface storage and discharge, and compare additional inlets with additional pumping for different bottlenecks. Also recalculate flow for the alternative rain value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 核對雨量單位和有效集水邊界，量測泵浦出流與集水井水位變化，以體積守恆互證。","textEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verify rainfall units and catchment boundaries, measure pump outflow and sump-level change, and cross-check them through volume conservation.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"將部分入口視為堵塞，建立地表暫存與排出的水量表；比較增加入口和增加泵量對不同瓶頸的效果。 再以本單元 rain 的對照值重算 flow，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Block selected inlets in the scenario, tabulate surface storage and discharge, and compare additional inlets with additional pumping for different bottlenecks. Also recalculate flow for the alternative rain value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「集水與排水容量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Catchment inflow and drainage capacity\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","設備可用度高就表示所有安全風險一定很低","現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","High equipment availability necessarily means every safety risk is low.","Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater."],"answer":2,"explanation":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b316-v16-12","title":"集水與排水容量：失效診斷","titleEn":"Catchment inflow and drainage capacity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-11"],"objective":"從症狀倒推「集水與排水容量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Catchment inflow and drainage capacity” and propose discriminating checks, corrective actions and prevention.","instruction":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 排水堵塞改變有效出流，不能只用較大泵浦銘牌值補償。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Blocked drainage changes effective outflow and cannot be compensated merely by a larger pump nameplate rating. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：檢查融雪水與排水溝通暢度如何改變路基附近的入流水量。","observationEn":"Link to the mechanism: Check how snowmelt and drain obstruction change water inflow beside the embankment.","failure":"誤判風險：若相信「排水管截面夠大就不需要檢查入口堵塞及下游水位」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A sufficiently large drain eliminates the need to check blocked inlets and tailwater.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 排水堵塞改變有效出流，不能只用較大泵浦銘牌值補償。","textEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Blocked drainage changes effective outflow and cannot be compensated merely by a larger pump nameplate rating.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「集水與排水容量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Catchment inflow and drainage capacity\" shows distress, which diagnosis is most reasonable?","options":["垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 需以量測區分可能原因。","explanationEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b316-v16-13","title":"長軌溫升與受限熱應力：機制與系統路徑","titleEn":"Long-rail temperature and restrained stress: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-12"],"objective":"說明「長軌溫升與受限熱應力」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Long-rail temperature and restrained stress” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。鎖定軌溫決定應力零點而空氣溫度不等於鋼軌溫度；實際扣件滑移與軌道側向阻力還會改變穩定問題。 溫差應相對於鋼軌實際無應力狀態，而非任意室溫。完全拘束估算給出軸向應力尺度；當扣件滑移或軌道彎曲出現時，需要位移相容和側向穩定分析。 將鋼軌熱應力與路基凍土熱狀態分為不同物理問題。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「長軌溫升與受限熱應力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. Stress-free rail temperature defines the reference and differs from air temperature. Fastener slip and lateral track resistance additionally govern stability, beyond the one-dimensional thermal-stress estimate. Temperature change must reference the rail’s actual stress-free state, not an arbitrary room temperature. Full restraint gives an axial stress scale. Fastener slip or track curvature requires displacement compatibility and lateral stability analysis beyond this expression. Treat rail thermal stress and the thermal condition of permafrost as distinct physical problems. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Long-rail temperature and restrained stress” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K；計算：compression=E*alpha*deltaT=73.1745 MPa。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K; calculation: compression=E*alpha*deltaT=73.1745 MPa.","failure":"常見誤解：「完全拘束的鋼軌升溫仍會無應力地自由伸長」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A fully restrained rail still expands freely without stress when heated.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「長軌溫升與受限熱應力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Long-rail temperature and restrained stress”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-13-k1","title":"長軌溫升與受限熱應力","titleEn":"Long-rail temperature and restrained stress","text":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。鎖定軌溫決定應力零點而空氣溫度不等於鋼軌溫度；實際扣件滑移與軌道側向阻力還會改變穩定問題。","textEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. Stress-free rail temperature defines the reference and differs from air temperature.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：完全拘束的鋼軌升溫仍會無應力地自由伸長 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A fully restrained rail still expands freely without stress when heated. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「長軌溫升與受限熱應力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Long-rail temperature and restrained stress\" is correct?","options":["完全拘束的鋼軌升溫仍會無應力地自由伸長","自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["A fully restrained rail still expands freely without stress when heated.","A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。 其餘選項是常見誤解。","explanationEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b316-v16-14","title":"長軌溫升與受限熱應力：定量估算","titleEn":"Long-rail temperature and restrained stress: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-13"],"objective":"以數值模型估算「長軌溫升與受限熱應力」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Long-rail temperature and restrained stress” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K；計算：compression=E*alpha*deltaT=73.1745 MPa。敏感度：deltaT 單獨增加百分之十至 33.33 K，其餘固定，結果為 80.49195 MPa。模型邊界：完全軸向拘束與線彈性；不計挫曲、初彎、殘留應力及塑性。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K; calculation: compression=E*alpha*deltaT=73.1745 MPa. Sensitivity: deltaT, increase this input alone by ten percent, to 33.33 K, with all other inputs fixed, gives 80.49195 MPa. Model boundary: Full axial restraint and linear elasticity; buckling, initial curvature, residual stress and plasticity are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。","observationEn":"How to cross-check: Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K；計算：compression=E*alpha*deltaT=73.1745 MPa。敏感度：deltaT 單獨增加百分之十至 33.33 K，其餘固定，結果為 80.49195 MPa。模型邊界：完全軸向拘束與線彈性；不計挫曲、初彎、殘留應力及塑性。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K; calculation: compression=E*alpha*deltaT=73.1745 MPa. Sensitivity: deltaT, increase this input alone by ten percent, to 33.33 K, with all other inputs fixed, gives 80.49195 MPa. Model boundary: Full axial restraint and linear elasticity; buckling, initial curvature, residual stress and plasticity are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「長軌溫升與受限熱應力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Long-rail temperature and restrained stress\", which statement holds?","options":["長下坡只需通過一次緊急停車試驗就能驗證持續制動","量測車速度提高時仍可永遠沿用原本取樣率","原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K。"],"optionsEn":["One emergency stop test verifies continuous braking capability on a long descent.","The original sampling rate remains sufficient at every increased inspection speed.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K；計算：compression=E*alpha*deltaT=73.1745 MPa。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.3 K; calculation: compression=E*alpha*deltaT=73.1745 MPa. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b316-v16-15","title":"長軌溫升與受限熱應力：試驗與驗證","titleEn":"Long-rail temperature and restrained stress: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「長軌溫升與受限熱應力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Long-rail temperature and restrained stress” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 以鋼軌接觸式溫度計校驗遙測值，核對應變零點，並保留日夜循環的升降溫路徑。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Calibrate remote readings against a contact rail thermometer, verify strain zero, and retain heating and cooling paths across the daily cycle. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：畫出自由、部分拘束與完全拘束三種邊界，重算熱變形或應力，標明哪些輸入必須由鋼軌溫度及扣件試驗取得。 再以本單元 deltaT 的對照值重算 compression，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Draw free, partial and full restraint boundaries, recalculate expansion or stress, and identify inputs requiring rail-temperature measurements and fastener tests. Also recalculate compression for the alternative deltaT value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 以鋼軌接觸式溫度計校驗遙測值，核對應變零點，並保留日夜循環的升降溫路徑。","textEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Calibrate remote readings against a contact rail thermometer, verify strain zero, and retain heating and cooling paths across the daily cycle.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"畫出自由、部分拘束與完全拘束三種邊界，重算熱變形或應力，標明哪些輸入必須由鋼軌溫度及扣件試驗取得。 再以本單元 deltaT 的對照值重算 compression，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Draw free, partial and full restraint boundaries, recalculate expansion or stress, and identify inputs requiring rail-temperature measurements and fastener tests. Also recalculate compression for the alternative deltaT value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「長軌溫升與受限熱應力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Long-rail temperature and restrained stress\"?","options":["量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。","不確定度太難估計，報告中只寫最佳值即可。","計算出的凍土融化厚度必定等於路基沉陷量"],"optionsEn":["Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour.","Uncertainty is too hard to estimate, so the report may state only the best value.","Calculated permafrost thaw depth necessarily equals embankment settlement."],"answer":0,"explanation":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b316-v16-16","title":"長軌溫升與受限熱應力：失效診斷","titleEn":"Long-rail temperature and restrained stress: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-15"],"objective":"從症狀倒推「長軌溫升與受限熱應力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Long-rail temperature and restrained stress” and propose discriminating checks, corrective actions and prevention.","instruction":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需查鎖定軌溫紀錄，不能以當天最低氣溫當無應力點。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Check stress-free-temperature records rather than using the day’s minimum air temperature as the reference. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將鋼軌熱應力與路基凍土熱狀態分為不同物理問題。","observationEn":"Link to the mechanism: Treat rail thermal stress and the thermal condition of permafrost as distinct physical problems.","failure":"誤判風險：若相信「完全拘束的鋼軌升溫仍會無應力地自由伸長」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A fully restrained rail still expands freely without stress when heated.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需查鎖定軌溫紀錄，不能以當天最低氣溫當無應力點。","textEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Check stress-free-temperature records rather than using the day’s minimum air temperature as the reference.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「長軌溫升與受限熱應力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Long-rail temperature and restrained stress\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Substituting air temperature misstates thermal loading.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需以量測區分可能原因。","explanationEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b316-v16-s3","title":"控制網與獨立量測殘差與高海拔壓力與氣體密度","titleEn":"Survey control and independent residuals & Altitude pressure and air density","description":"本階段聚焦「控制網與獨立量測殘差」與「高海拔壓力與氣體密度」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Survey control and independent residuals\" and \"Altitude pressure and air density\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b316-v16-17","title":"控制網與獨立量測殘差：機制與系統路徑","titleEn":"Survey control and independent residuals: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-16"],"objective":"說明「控制網與獨立量測殘差」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Survey control and independent residuals” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。共同基點錯誤會同時影響兩套結果，控制網需要閉合檢查及外部基準才能發現系統偏差。 兩座標差的歐氏長度表示平面殘差大小，不是隨機標準差。先把兩套座標轉到相同基準和單位，再檢查各方向偏差；共同平移可能讓相對殘差很小但絕對位置仍錯。 用穩定外部基點檢查長期高程趨勢，避免基點同時移動。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「控制網與獨立量測殘差」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. A shared control-point error affects both results. Network closure and an external datum are needed to reveal systematic bias that agreement alone can conceal. The Euclidean length of two coordinate differences measures planar residual, not random standard deviation. Transform both coordinate sets to one datum and unit before inspecting directional differences. Common translation can leave a small relative residual while absolute position remains wrong. Check long-term elevation trends against a stable external datum rather than a moving local reference. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Survey control and independent residuals” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：dx=0.00303 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00303 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm.","failure":"常見誤解：「兩台儀器量得同樣座標就證明座標絕對正確」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Matching coordinates from two instruments prove absolute coordinate accuracy.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「控制網與獨立量測殘差」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Survey control and independent residuals”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-17-k1","title":"控制網與獨立量測殘差","titleEn":"Survey control and independent residuals","text":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。共同基點錯誤會同時影響兩套結果，控制網需要閉合檢查及外部基準才能發現系統偏差。","textEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. A shared control-point error affects both results.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩台儀器量得同樣座標就證明座標絕對正確 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Matching coordinates from two instruments prove absolute coordinate accuracy. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「控制網與獨立量測殘差」，下列哪一項敘述正確？","questionEn":"Which statement about \"Survey control and independent residuals\" is correct?","options":["兩台儀器量得同樣座標就證明座標絕對正確","空氣體積流率相同就表示任何海拔的散熱質量流率相同","兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。"],"optionsEn":["Matching coordinates from two instruments prove absolute coordinate accuracy.","Equal volumetric airflow guarantees equal cooling mass flow at every altitude.","The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy."],"answer":2,"explanation":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。 其餘選項是常見誤解。","explanationEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b316-v16-18","title":"控制網與獨立量測殘差：定量估算","titleEn":"Survey control and independent residuals: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-17"],"objective":"以數值模型估算「控制網與獨立量測殘差」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Survey control and independent residuals” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：dx=0.00303 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm。敏感度：dx 單獨增加百分之十至 0.003333 m，其餘固定，結果為 5.20662 mm。模型邊界：平面兩分量殘差；不含座標轉換協方差和垂直誤差。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00303 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm. Sensitivity: dx, increase this input alone by ten percent, to 0.003333 m, with all other inputs fixed, gives 5.20662 mm. Model boundary: Planar two-component residual; transformation covariance and vertical error are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。","observationEn":"How to cross-check: Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：dx=0.00303 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm。敏感度：dx 單獨增加百分之十至 0.003333 m，其餘固定，結果為 5.20662 mm。模型邊界：平面兩分量殘差；不含座標轉換協方差和垂直誤差。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00303 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm. Sensitivity: dx, increase this input alone by ten percent, to 0.003333 m, with all other inputs fixed, gives 5.20662 mm. Model boundary: Planar two-component residual; transformation covariance and vertical error are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「控制網與獨立量測殘差」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Survey control and independent residuals\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：dx=0.00303 m; dy=0.004 m。","電機額定扭矩夠大就不需要考慮輪軌黏著","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["Original hypothetical exercise.","A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：dx=0.00303 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00303 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.018057 mm. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b316-v16-19","title":"控制網與獨立量測殘差：試驗與驗證","titleEn":"Survey control and independent residuals: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「控制網與獨立量測殘差」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Survey control and independent residuals” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 以反向觀測、閉合路線和外部基準交叉檢核，分開報告平面殘差與可疑共同偏差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Cross-check reversed observations, closed loops and external references, reporting planar residual separately from suspected shared bias. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：加入一個共同平移偏差，檢查兩儀器殘差與外部基準差異，提出能辨識系統誤差的控制網配置。 再以本單元 dx 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Add a shared translation bias, compare inter-instrument residual with error to an external datum, and propose a control network that can reveal systematic error. Also recalculate residual for the alternative dx value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 以反向觀測、閉合路線和外部基準交叉檢核，分開報告平面殘差與可疑共同偏差。","textEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Cross-check reversed observations, closed loops and external references, reporting planar residual separately from suspected shared bias.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"加入一個共同平移偏差，檢查兩儀器殘差與外部基準差異，提出能辨識系統誤差的控制網配置。 再以本單元 dx 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Add a shared translation bias, compare inter-instrument residual with error to an external datum, and propose a control network that can reveal systematic error. Also recalculate residual for the alternative dx value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「控制網與獨立量測殘差」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Survey control and independent residuals\"?","options":["允收準則可以等看到量測數據後再決定。","用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b316-v16-20","title":"控制網與獨立量測殘差：失效診斷","titleEn":"Survey control and independent residuals: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-19"],"objective":"從症狀倒推「控制網與獨立量測殘差」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Survey control and independent residuals” and propose discriminating checks, corrective actions and prevention.","instruction":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 閉合良好仍可能全部同向漂移，須使用外部穩定基準。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Good closure can coexist with common drift; an external stable reference remains necessary. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：用穩定外部基點檢查長期高程趨勢，避免基點同時移動。","observationEn":"Link to the mechanism: Check long-term elevation trends against a stable external datum rather than a moving local reference.","failure":"誤判風險：若相信「兩台儀器量得同樣座標就證明座標絕對正確」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Matching coordinates from two instruments prove absolute coordinate accuracy.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 閉合良好仍可能全部同向漂移，須使用外部穩定基準。","textEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Good closure can coexist with common drift; an external stable reference remains necessary.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「控制網與獨立量測殘差」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Survey control and independent residuals\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","空氣體積流率相同就表示任何海拔的散熱質量流率相同","同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Equal volumetric airflow guarantees equal cooling mass flow at every altitude.","One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error."],"answer":2,"explanation":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 需以量測區分可能原因。","explanationEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b316-v16-21","title":"高海拔壓力與氣體密度：機制與系統路徑","titleEn":"Altitude pressure and air density: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-20"],"objective":"說明「高海拔壓力與氣體密度」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Altitude pressure and air density” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"理想氣體密度由絕對壓力除氣體常數與絕對溫度決定，高海拔低壓會減少同體積空氣所攜帶的質量。這同時影響散熱和氣動力，但車廂供氧與醫療需求不能由密度公式單獨決定。 此理想氣體式以絕對壓力和絕對溫度估算空氣密度，壓力不代表氧氣比例。高原環境的密度可影響氣動和冷卻估算，但人員生理與主動加壓系統需要另外分析。 以高原絕對氣壓與溫度計算空氣密度，另列含氧與生理議題。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「高海拔壓力與氣體密度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Ideal-gas density is absolute pressure divided by gas constant and absolute temperature. Lower pressure at altitude reduces the mass carried in a fixed air volume, affecting cooling and aerodynamic loads. Cabin oxygen provision and medical needs cannot be determined by density alone. This ideal-gas expression estimates air density from absolute pressure and temperature; pressure is not an oxygen fraction. Altitude-dependent density can affect aerodynamic and cooling estimates, while human physiology and active pressurisation require separate analysis. Calculate air density from altitude pressure and temperature, separately identifying oxygen and physiological questions. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Altitude pressure and air density” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K；計算：density=pressure/(Rair*temperature)=0.7541065 kg/m^3。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K; calculation: density=pressure/(Rair*temperature)=0.7541065 kg/m^3.","failure":"常見誤解：「空氣體積流率相同就表示任何海拔的散熱質量流率相同」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal volumetric airflow guarantees equal cooling mass flow at every altitude.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「高海拔壓力與氣體密度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Altitude pressure and air density”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-21-k1","title":"高海拔壓力與氣體密度","titleEn":"Altitude pressure and air density","text":"理想氣體密度由絕對壓力除氣體常數與絕對溫度決定，高海拔低壓會減少同體積空氣所攜帶的質量。這同時影響散熱和氣動力，但車廂供氧與醫療需求不能由密度公式單獨決定。","textEn":"Ideal-gas density is absolute pressure divided by gas constant and absolute temperature. Lower pressure at altitude reduces the mass carried in a fixed air volume, affecting cooling and aerodynamic loads.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：空氣體積流率相同就表示任何海拔的散熱質量流率相同 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal volumetric airflow guarantees equal cooling mass flow at every altitude. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「高海拔壓力與氣體密度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Altitude pressure and air density\" is correct?","options":["理想氣體密度由絕對壓力除氣體常數與絕對溫度決定，高海拔低壓會減少同體積空氣所攜帶的質量。","空氣體積流率相同就表示任何海拔的散熱質量流率相同","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Ideal-gas density is absolute pressure divided by gas constant and absolute temperature.","Equal volumetric airflow guarantees equal cooling mass flow at every altitude.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":0,"explanation":"理想氣體密度由絕對壓力除氣體常數與絕對溫度決定，高海拔低壓會減少同體積空氣所攜帶的質量。 其餘選項是常見誤解。","explanationEn":"Ideal-gas density is absolute pressure divided by gas constant and absolute temperature. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b316-v16-22","title":"高海拔壓力與氣體密度：定量估算","titleEn":"Altitude pressure and air density: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-21"],"objective":"以數值模型估算「高海拔壓力與氣體密度」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Altitude pressure and air density” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K；計算：density=pressure/(Rair*temperature)=0.7541065 kg/m^3。敏感度：pressure 單獨增加百分之十至 66660 Pa，其餘固定，結果為 0.8295172 kg/m^3。模型邊界：乾空氣理想氣體、均勻壓溫；不計濕度與生理反應。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K; calculation: density=pressure/(Rair*temperature)=0.7541065 kg/m^3. Sensitivity: pressure, increase this input alone by ten percent, to 66660 Pa, with all other inputs fixed, gives 0.8295172 kg/m^3. Model boundary: Dry ideal air at uniform pressure and temperature; humidity and physiological response are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：使用絕對壓力計與校正溫度計，核對感測器是否誤報表壓，並用已知風量估算質量流率檢查冷卻設計假設。","observationEn":"How to cross-check: Use absolute-pressure and calibrated temperature sensors, check that gauge pressure is not mistaken for absolute pressure, and compare mass flow inferred from measured volume flow.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K；計算：density=pressure/(Rair*temperature)=0.7541065 kg/m^3。敏感度：pressure 單獨增加百分之十至 66660 Pa，其餘固定，結果為 0.8295172 kg/m^3。模型邊界：乾空氣理想氣體、均勻壓溫；不計濕度與生理反應。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K; calculation: density=pressure/(Rair*temperature)=0.7541065 kg/m^3. Sensitivity: pressure, increase this input alone by ten percent, to 66660 Pa, with all other inputs fixed, gives 0.8295172 kg/m^3. Model boundary: Dry ideal air at uniform pressure and temperature; humidity and physiological response are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「高海拔壓力與氣體密度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Altitude pressure and air density\", which statement holds?","options":["量測車速度提高時仍可永遠沿用原本取樣率","原創假想算例，全部輸入均非本工程操作參數：pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K。","計算出的凍土融化厚度必定等於路基沉陷量"],"optionsEn":["The original sampling rate remains sufficient at every increased inspection speed.","Original hypothetical exercise.","Calculated permafrost thaw depth necessarily equals embankment settlement."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K；計算：density=pressure/(Rair*temperature)=0.7541065 kg/m^3。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: pressure=60600 Pa; Rair=287 J/(kg*K); temperature=280 K; calculation: density=pressure/(Rair*temperature)=0.7541065 kg/m^3. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b316-v16-23","title":"高海拔壓力與氣體密度：試驗與驗證","titleEn":"Altitude pressure and air density: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「高海拔壓力與氣體密度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Altitude pressure and air density” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"使用絕對壓力計與校正溫度計，核對感測器是否誤報表壓，並用已知風量估算質量流率檢查冷卻設計假設。 校正絕對壓力計並量測同位置氣溫，核對溫標換算，必要時另列濕度造成的氣體性質差異。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use absolute-pressure and calibrated temperature sensors, check that gauge pressure is not mistaken for absolute pressure, and compare mass flow inferred from measured volume flow. Calibrate the absolute-pressure sensor and measure temperature at the same location, checking the temperature conversion and separately considering humidity effects. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較兩種絕對壓力下的密度與同風量質量流率，標註溫標換算，再說明哪些車廂環境議題需要其他專業模型。 再以本單元 pressure 的對照值重算 density，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare density and mass flow at two absolute pressures, show temperature-scale conversion, and identify cabin-environment questions requiring additional specialised models. Also recalculate density for the alternative pressure value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：把攝氏溫度直接代入氣體公式會產生巨大誤差；低密度時沿用海平面風量又可能不足以移除同一熱負載。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Using Celsius directly in the gas equation creates a large error; at low density, sea-level volume flow may not remove the same heat load. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"使用絕對壓力計與校正溫度計，核對感測器是否誤報表壓，並用已知風量估算質量流率檢查冷卻設計假設。 校正絕對壓力計並量測同位置氣溫，核對溫標換算，必要時另列濕度造成的氣體性質差異。","textEn":"Use absolute-pressure and calibrated temperature sensors, check that gauge pressure is not mistaken for absolute pressure, and compare mass flow inferred from measured volume flow. Calibrate the absolute-pressure sensor and measure temperature at the same location, checking the temperature conversion and separately considering humidity effects.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"比較兩種絕對壓力下的密度與同風量質量流率，標註溫標換算，再說明哪些車廂環境議題需要其他專業模型。 再以本單元 pressure 的對照值重算 density，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare density and mass flow at two absolute pressures, show temperature-scale conversion, and identify cabin-environment questions requiring additional specialised models. Also recalculate density for the alternative pressure value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「高海拔壓力與氣體密度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Altitude pressure and air density\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","排水管截面夠大就不需要檢查入口堵塞及下游水位","使用絕對壓力計與校正溫度計，核對感測器是否誤報表壓，並用已知風量估算質量流率檢查冷卻設計假設。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","Use absolute-pressure and calibrated temperature sensors, check that gauge pressure is not mistaken for absolute pressure, and compare mass flow inferred from measured volume flow."],"answer":2,"explanation":"使用絕對壓力計與校正溫度計，核對感測器是否誤報表壓，並用已知風量估算質量流率檢查冷卻設計假設。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use absolute-pressure and calibrated temperature sensors, check that gauge pressure is not mistaken for absolute pressure, and compare mass flow inferred from measured volume flow. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b316-v16-24","title":"高海拔壓力與氣體密度：失效診斷","titleEn":"Altitude pressure and air density: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-23"],"objective":"從症狀倒推「高海拔壓力與氣體密度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Altitude pressure and air density” and propose discriminating checks, corrective actions and prevention.","instruction":"把攝氏溫度直接代入氣體公式會產生巨大誤差；低密度時沿用海平面風量又可能不足以移除同一熱負載。 若使用攝氏溫度直接作分母，空氣密度會失去正確物理意義。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Using Celsius directly in the gas equation creates a large error; at low density, sea-level volume flow may not remove the same heat load. Using Celsius temperature directly in the denominator produces a physically incorrect air density. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：以高原絕對氣壓與溫度計算空氣密度，另列含氧與生理議題。","observationEn":"Link to the mechanism: Calculate air density from altitude pressure and temperature, separately identifying oxygen and physiological questions.","failure":"誤判風險：若相信「空氣體積流率相同就表示任何海拔的散熱質量流率相同」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal volumetric airflow guarantees equal cooling mass flow at every altitude.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"把攝氏溫度直接代入氣體公式會產生巨大誤差；低密度時沿用海平面風量又可能不足以移除同一熱負載。 若使用攝氏溫度直接作分母，空氣密度會失去正確物理意義。","textEn":"Using Celsius directly in the gas equation creates a large error; at low density, sea-level volume flow may not remove the same heat load. Using Celsius temperature directly in the denominator produces a physically incorrect air density.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「高海拔壓力與氣體密度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Altitude pressure and air density\" shows distress, which diagnosis is most reasonable?","options":["把攝氏溫度直接代入氣體公式會產生巨大誤差；低密度時沿用海平面風量又可能不足以移除同一熱負載。","只要結構還沒倒，就代表安全餘裕仍然足夠。","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Using Celsius directly in the gas equation creates a large error; at low density, sea-level volume flow may not remove the same heat load.","As long as the structure is still standing, its safety margin must still be adequate.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":0,"explanation":"把攝氏溫度直接代入氣體公式會產生巨大誤差；低密度時沿用海平面風量又可能不足以移除同一熱負載。 需以量測區分可能原因。","explanationEn":"Using Celsius directly in the gas equation creates a large error; at low density, sea-level volume flow may not remove the same heat load. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b316-v16-s4","title":"坡度阻力與爬坡功率與黏著限制與可用牽引力","titleEn":"Gradient resistance and climbing power & Adhesion limit and usable traction","description":"本階段聚焦「坡度阻力與爬坡功率」與「黏著限制與可用牽引力」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Gradient resistance and climbing power\" and \"Adhesion limit and usable traction\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b316-v16-25","title":"坡度阻力與爬坡功率：機制與系統路徑","titleEn":"Gradient resistance and climbing power: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-24"],"objective":"說明「坡度阻力與爬坡功率」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Gradient resistance and climbing power” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。功率還與速度相乘，因此相同牽引力下高速爬坡更耗功率；下坡則需處理持續制動能量而非僅一次停車。 坡度以升高量除以水平距離表示，百分比與小數不可混用。此項只表示重力位能增加的速率，總牽引功率還要加上加速、滾動、氣動及轉換損失。 比較高原坡道的重力功率與額外阻力，不把海拔當成坡度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「坡度阻力與爬坡功率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Climbing raises gravitational potential energy. For small gradients, the along-track gravity force is approximately weight times gradient. Multiplication by speed gives power, making faster climbing more demanding at equal force; descending requires continuous energy management rather than merely one stopping event. Gradient is rise divided by horizontal distance, so percentage and decimal representations must not be mixed. This term only gives the rate of gravitational potential-energy increase. Total traction demand also includes acceleration, rolling resistance, aerodynamics and conversion losses. Compare gradient power with other resistance at altitude without treating elevation itself as gradient. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Gradient resistance and climbing power” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mass=303000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2377.944 kW。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=303000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2377.944 kW.","failure":"常見誤解：「長下坡只需通過一次緊急停車試驗就能驗證持續制動」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"One emergency stop test verifies continuous braking capability on a long descent.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「坡度阻力與爬坡功率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Gradient resistance and climbing power”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-25-k1","title":"坡度阻力與爬坡功率","titleEn":"Gradient resistance and climbing power","text":"列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。功率還與速度相乘，因此相同牽引力下高速爬坡更耗功率；下坡則需處理持續制動能量而非僅一次停車。","textEn":"Climbing raises gravitational potential energy. For small gradients, the along-track gravity force is approximately weight times gradient.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：長下坡只需通過一次緊急停車試驗就能驗證持續制動 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: One emergency stop test verifies continuous braking capability on a long descent. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「坡度阻力與爬坡功率」，下列哪一項敘述正確？","questionEn":"Which statement about \"Gradient resistance and climbing power\" is correct?","options":["長下坡只需通過一次緊急停車試驗就能驗證持續制動","列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。","電機額定扭矩夠大就不需要考慮輪軌黏著"],"optionsEn":["One emergency stop test verifies continuous braking capability on a long descent.","Climbing raises gravitational potential energy.","A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion."],"answer":1,"explanation":"列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。 其餘選項是常見誤解。","explanationEn":"Climbing raises gravitational potential energy. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b316-v16-26","title":"坡度阻力與爬坡功率：定量估算","titleEn":"Gradient resistance and climbing power: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-25"],"objective":"以數值模型估算「坡度阻力與爬坡功率」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Gradient resistance and climbing power” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mass=303000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2377.944 kW。敏感度：mass 單獨增加百分之十至 333300 kg，其餘固定，結果為 2615.738 kW。模型邊界：小坡度且定速；不含空阻、輪阻、加速與傳動損失。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=303000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2377.944 kW. Sensitivity: mass, increase this input alone by ten percent, to 333300 kg, with all other inputs fixed, gives 2615.738 kW. Model boundary: Small gradient and constant speed; aerodynamic drag, rolling resistance, acceleration and drive losses are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。","observationEn":"How to cross-check: Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mass=303000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2377.944 kW。敏感度：mass 單獨增加百分之十至 333300 kg，其餘固定，結果為 2615.738 kW。模型邊界：小坡度且定速；不含空阻、輪阻、加速與傳動損失。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=303000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2377.944 kW. Sensitivity: mass, increase this input alone by ten percent, to 333300 kg, with all other inputs fixed, gives 2615.738 kW. Model boundary: Small gradient and constant speed; aerodynamic drag, rolling resistance, acceleration and drive losses are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「坡度阻力與爬坡功率」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Gradient resistance and climbing power\", which statement holds?","options":["設備可用度高就表示所有安全風險一定很低","兩端高程相同就能證明兩點之間沒有差異沉陷","原創假想算例，全部輸入均非本工程操作參數：mass=303000 kg; gradient=0.02 1; v=40 m/s。"],"optionsEn":["High equipment availability necessarily means every safety risk is low.","Equal endpoint elevations prove there is no differential settlement between them.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mass=303000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2377.944 kW。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=303000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2377.944 kW. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b316-v16-27","title":"坡度阻力與爬坡功率：試驗與驗證","titleEn":"Gradient resistance and climbing power: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「坡度阻力與爬坡功率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Gradient resistance and climbing power” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。 由高程剖面核對坡度，使用同一時間窗比對速度與牽引功率，另列非重力負載。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent. Check gradient from the elevation profile, compare speed and traction power over one time window, and list non-gravitational loads separately. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用相同高差設計長緩坡與短陡坡，對比理想位能和峰值功率，指出兩者為何不能用同一項設備額定值評估。 再以本單元 mass 的對照值重算 climbing，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Design a long gentle and short steep climb with equal height gain, compare ideal energy and peak power, and explain why one equipment rating cannot evaluate both. Also recalculate climbing for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。 由高程剖面核對坡度，使用同一時間窗比對速度與牽引功率，另列非重力負載。","textEn":"Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent. Check gradient from the elevation profile, compare speed and traction power over one time window, and list non-gravitational loads separately.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"用相同高差設計長緩坡與短陡坡，對比理想位能和峰值功率，指出兩者為何不能用同一項設備額定值評估。 再以本單元 mass 的對照值重算 climbing，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Design a long gentle and short steep climb with equal height gain, compare ideal energy and peak power, and explain why one equipment rating cannot evaluate both. Also recalculate climbing for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「坡度阻力與爬坡功率」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Gradient resistance and climbing power\"?","options":["以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b316-v16-28","title":"坡度阻力與爬坡功率：失效診斷","titleEn":"Gradient resistance and climbing power: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-27"],"objective":"從症狀倒推「坡度阻力與爬坡功率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Gradient resistance and climbing power” and propose discriminating checks, corrective actions and prevention.","instruction":"忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 功率不足時須分辨坡度阻力與黏著限制，不能只加大電流。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. When power is insufficient, distinguish gradient resistance from adhesion limits rather than only increasing current. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較高原坡道的重力功率與額外阻力，不把海拔當成坡度。","observationEn":"Link to the mechanism: Compare gradient power with other resistance at altitude without treating elevation itself as gradient.","failure":"誤判風險：若相信「長下坡只需通過一次緊急停車試驗就能驗證持續制動」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"One emergency stop test verifies continuous braking capability on a long descent.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 功率不足時須分辨坡度阻力與黏著限制，不能只加大電流。","textEn":"Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. When power is insufficient, distinguish gradient resistance from adhesion limits rather than only increasing current.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「坡度阻力與爬坡功率」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Gradient resistance and climbing power\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。","電機額定扭矩夠大就不需要考慮輪軌黏著"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Ignoring sustained downhill heat confuses short-term braking capability with continuous rating.","A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion."],"answer":1,"explanation":"忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 需以量測區分可能原因。","explanationEn":"Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b316-v16-29","title":"黏著限制與可用牽引力：機制與系統路徑","titleEn":"Adhesion limit and usable traction: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-28"],"objective":"說明「黏著限制與可用牽引力」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Adhesion limit and usable traction” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"牽引力需要透過接觸斑傳到軌道，簡化上限與黏著係數及動輪法向力相乘。電機能提供更大扭矩不代表輪軌能傳遞；雨水、落葉與速度都會改變接觸狀態，使固定係數模型失去精度。 法向荷重應只取實際驅動接觸點的總量，不能自動使用整列重量。此上限也不描述黏著峰後的滑移控制；若輪重轉移，就要以每個接觸點重新分配。 在凍結或融水條件下比較黏著上限，保留試驗範圍。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「黏著限制與可用牽引力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Traction reaches the track through contact patches. A simple upper bound multiplies adhesion coefficient by normal force on driven wheels. More motor torque does not guarantee more transmitted force; rain, leaves and speed alter contact conditions and limit the accuracy of a fixed coefficient. Normal load must include only the driven contacts, not automatically the weight of the whole train. This bound does not describe slip control beyond the adhesion peak. Wheel-load transfer requires a new allocation across individual contact points. Compare adhesion bounds under freezing or meltwater conditions while retaining the experimental range. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Adhesion limit and usable traction” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mu=0.1818 1; weight=900000 N；計算：traction=mu*weight/1000=163.62 kN。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mu=0.1818 1; weight=900000 N; calculation: traction=mu*weight/1000=163.62 kN.","failure":"常見誤解：「電機額定扭矩夠大就不需要考慮輪軌黏著」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「黏著限制與可用牽引力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Adhesion limit and usable traction”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-29-k1","title":"黏著限制與可用牽引力","titleEn":"Adhesion limit and usable traction","text":"牽引力需要透過接觸斑傳到軌道，簡化上限與黏著係數及動輪法向力相乘。電機能提供更大扭矩不代表輪軌能傳遞；雨水、落葉與速度都會改變接觸狀態，使固定係數模型失去精度。","textEn":"Traction reaches the track through contact patches. A simple upper bound multiplies adhesion coefficient by normal force on driven wheels.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：電機額定扭矩夠大就不需要考慮輪軌黏著 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「黏著限制與可用牽引力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Adhesion limit and usable traction\" is correct?","options":["電機額定扭矩夠大就不需要考慮輪軌黏著","量測車速度提高時仍可永遠沿用原本取樣率","牽引力需要透過接觸斑傳到軌道，簡化上限與黏著係數及動輪法向力相乘。"],"optionsEn":["A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion.","The original sampling rate remains sufficient at every increased inspection speed.","Traction reaches the track through contact patches."],"answer":2,"explanation":"牽引力需要透過接觸斑傳到軌道，簡化上限與黏著係數及動輪法向力相乘。 其餘選項是常見誤解。","explanationEn":"Traction reaches the track through contact patches. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b316-v16-30","title":"黏著限制與可用牽引力：定量估算","titleEn":"Adhesion limit and usable traction: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-29"],"objective":"以數值模型估算「黏著限制與可用牽引力」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Adhesion limit and usable traction” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mu=0.1818 1; weight=900000 N；計算：traction=mu*weight/1000=163.62 kN。敏感度：mu 單獨增加百分之十至 0.19998 1，其餘固定，結果為 179.982 kN。模型邊界：準靜態庫倫上限與均勻輪重；未建模蠕滑曲線及動態減載。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mu=0.1818 1; weight=900000 N; calculation: traction=mu*weight/1000=163.62 kN. Sensitivity: mu, increase this input alone by ten percent, to 0.19998 1, with all other inputs fixed, gives 179.982 kN. Model boundary: Quasi-static Coulomb bound with uniform wheel load; creep curves and dynamic unloading are not modelled. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：比較輪速、列車獨立速度與牽引電流，找出滑轉開始點；濕乾條件必須分組，不能用全日平均係數掩蓋低黏著尾端。","observationEn":"How to cross-check: Compare wheel speed, independently measured train speed and traction current to locate slip onset, separating wet and dry conditions rather than hiding low-adhesion tails in a daily mean.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mu=0.1818 1; weight=900000 N；計算：traction=mu*weight/1000=163.62 kN。敏感度：mu 單獨增加百分之十至 0.19998 1，其餘固定，結果為 179.982 kN。模型邊界：準靜態庫倫上限與均勻輪重；未建模蠕滑曲線及動態減載。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mu=0.1818 1; weight=900000 N; calculation: traction=mu*weight/1000=163.62 kN. Sensitivity: mu, increase this input alone by ten percent, to 0.19998 1, with all other inputs fixed, gives 179.982 kN. Model boundary: Quasi-static Coulomb bound with uniform wheel load; creep curves and dynamic unloading are not modelled.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「黏著限制與可用牽引力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Adhesion limit and usable traction\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：mu=0.1818 1; weight=900000 N。","計算出的凍土融化厚度必定等於路基沉陷量","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Original hypothetical exercise.","Calculated permafrost thaw depth necessarily equals embankment settlement.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mu=0.1818 1; weight=900000 N；計算：traction=mu*weight/1000=163.62 kN。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mu=0.1818 1; weight=900000 N; calculation: traction=mu*weight/1000=163.62 kN. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b316-v16-31","title":"黏著限制與可用牽引力：試驗與驗證","titleEn":"Adhesion limit and usable traction: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「黏著限制與可用牽引力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Adhesion limit and usable traction” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"比較輪速、列車獨立速度與牽引電流，找出滑轉開始點；濕乾條件必須分組，不能用全日平均係數掩蓋低黏著尾端。 以獨立地速校對輪周速度，核實輪徑設定，再按乾濕條件與軸荷分類比對。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare wheel speed, independently measured train speed and traction current to locate slip onset, separating wet and dry conditions rather than hiding low-adhesion tails in a daily mean. Calibrate wheel-periphery speed against independent ground speed, verify wheel-diameter settings, and compare results by wetness condition and axle load. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：把黏著係數減半並比較動輪荷重調整，計算牽引上限，解釋為何撒砂或控制策略的效果需用試驗而不能只看馬達功率。 再以本單元 mu 的對照值重算 traction，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Halve adhesion and compare a change in driven-wheel load, calculate traction bounds, and explain why sanding or control performance requires tests rather than motor-power data alone. Also recalculate traction for the alternative mu value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只提高扭矩可能觸發滑轉並降低可控牽引；輪徑設定誤差也會製造假的滑差，需以獨立地速判別。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Increasing torque can trigger slip and reduce controllable traction; an incorrect wheel diameter also creates apparent slip, requiring independent ground-speed evidence. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"比較輪速、列車獨立速度與牽引電流，找出滑轉開始點；濕乾條件必須分組，不能用全日平均係數掩蓋低黏著尾端。 以獨立地速校對輪周速度，核實輪徑設定，再按乾濕條件與軸荷分類比對。","textEn":"Compare wheel speed, independently measured train speed and traction current to locate slip onset, separating wet and dry conditions rather than hiding low-adhesion tails in a daily mean. Calibrate wheel-periphery speed against independent ground speed, verify wheel-diameter settings, and compare results by wetness condition and axle load.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"把黏著係數減半並比較動輪荷重調整，計算牽引上限，解釋為何撒砂或控制策略的效果需用試驗而不能只看馬達功率。 再以本單元 mu 的對照值重算 traction，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Halve adhesion and compare a change in driven-wheel load, calculate traction bounds, and explain why sanding or control performance requires tests rather than motor-power data alone. Also recalculate traction for the alternative mu value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「黏著限制與可用牽引力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Adhesion limit and usable traction\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","比較輪速、列車獨立速度與牽引電流，找出滑轉開始點；濕乾條件必須分組，不能用全日平均係數掩蓋低黏著尾端。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Compare wheel speed, independently measured train speed and traction current to locate slip onset, separating wet and dry conditions rather than hiding low-adhesion tails in a daily mean.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"比較輪速、列車獨立速度與牽引電流，找出滑轉開始點；濕乾條件必須分組，不能用全日平均係數掩蓋低黏著尾端。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare wheel speed, independently measured train speed and traction current to locate slip onset, separating wet and dry conditions rather than hiding low-adhesion tails in a daily mean. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b316-v16-32","title":"黏著限制與可用牽引力：失效診斷","titleEn":"Adhesion limit and usable traction: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-31"],"objective":"從症狀倒推「黏著限制與可用牽引力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Adhesion limit and usable traction” and propose discriminating checks, corrective actions and prevention.","instruction":"只提高扭矩可能觸發滑轉並降低可控牽引；輪徑設定誤差也會製造假的滑差，需以獨立地速判別。 先查輪徑與地速誤差，避免把量測偏差當成真滑轉。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Increasing torque can trigger slip and reduce controllable traction; an incorrect wheel diameter also creates apparent slip, requiring independent ground-speed evidence. Check diameter and ground-speed errors before interpreting measurement bias as actual wheel slip. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在凍結或融水條件下比較黏著上限，保留試驗範圍。","observationEn":"Link to the mechanism: Compare adhesion bounds under freezing or meltwater conditions while retaining the experimental range.","failure":"誤判風險：若相信「電機額定扭矩夠大就不需要考慮輪軌黏著」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A sufficiently large rated motor torque eliminates the need to consider wheel-rail adhesion.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"只提高扭矩可能觸發滑轉並降低可控牽引；輪徑設定誤差也會製造假的滑差，需以獨立地速判別。 先查輪徑與地速誤差，避免把量測偏差當成真滑轉。","textEn":"Increasing torque can trigger slip and reduce controllable traction; an incorrect wheel diameter also creates apparent slip, requiring independent ground-speed evidence. Check diameter and ground-speed errors before interpreting measurement bias as actual wheel slip.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「黏著限制與可用牽引力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Adhesion limit and usable traction\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","量測車速度提高時仍可永遠沿用原本取樣率","只提高扭矩可能觸發滑轉並降低可控牽引；輪徑設定誤差也會製造假的滑差，需以獨立地速判別。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","The original sampling rate remains sufficient at every increased inspection speed.","Increasing torque can trigger slip and reduce controllable traction."],"answer":2,"explanation":"只提高扭矩可能觸發滑轉並降低可控牽引；輪徑設定誤差也會製造假的滑差，需以獨立地速判別。 需以量測區分可能原因。","explanationEn":"Increasing torque can trigger slip and reduce controllable traction; an incorrect wheel diameter also creates apparent slip, requiring independent ground-speed evidence. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b316-v16-s5","title":"空間波長與量測取樣與可用度與修復時間","titleEn":"Spatial wavelength and sampling & Availability and repair time","description":"本階段聚焦「空間波長與量測取樣」與「可用度與修復時間」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Spatial wavelength and sampling\" and \"Availability and repair time\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b316-v16-33","title":"空間波長與量測取樣：機制與系統路徑","titleEn":"Spatial wavelength and sampling: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-32"],"objective":"說明「空間波長與量測取樣」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Spatial wavelength and sampling” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"移動量測車把軌道空間波長轉成時間頻率，速度除波長得到激振頻率。要避免混疊，取樣率需高於訊號頻寬兩倍並搭配抗混疊濾波；提高取樣率本身不能修正輪滑造成的里程誤差。 取樣頻率超過訊號最高頻率兩倍是重建的必要起點，仍需要抗混疊濾波及足夠振幅精度。尖峰與非平穩事件的要求不同，應從量測目的回推頻寬與記錄長度。 選擇足以分辨日夜熱循環與列車振動的不同取樣頻率。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「空間波長與量測取樣」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A moving inspection vehicle converts track wavelength into temporal frequency through speed divided by wavelength. Avoiding aliasing requires a sampling rate above twice the signal bandwidth and an antialias filter. A higher sample rate alone cannot correct distance errors caused by wheel slip. Sampling above twice the highest signal frequency is a starting condition for reconstruction, but anti-alias filtering and amplitude accuracy remain necessary. Peaks and nonstationary events have different needs; derive bandwidth and recording duration from the measurement objective. Choose different sampling rates for daily thermal cycles and train-induced vibration. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Spatial wavelength and sampling” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：speed=50.5 m/s; wavelength=2 m；計算：nyquist_lower_bound=2*speed/wavelength=50.5 samples/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=50.5 m/s; wavelength=2 m; calculation: nyquist_lower_bound=2*speed/wavelength=50.5 samples/s.","failure":"常見誤解：「量測車速度提高時仍可永遠沿用原本取樣率」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The original sampling rate remains sufficient at every increased inspection speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「空間波長與量測取樣」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Spatial wavelength and sampling”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-33-k1","title":"空間波長與量測取樣","titleEn":"Spatial wavelength and sampling","text":"移動量測車把軌道空間波長轉成時間頻率，速度除波長得到激振頻率。要避免混疊，取樣率需高於訊號頻寬兩倍並搭配抗混疊濾波；提高取樣率本身不能修正輪滑造成的里程誤差。","textEn":"A moving inspection vehicle converts track wavelength into temporal frequency through speed divided by wavelength. Avoiding aliasing requires a sampling rate above twice the signal bandwidth and an antialias filter.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：量測車速度提高時仍可永遠沿用原本取樣率 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The original sampling rate remains sufficient at every increased inspection speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「空間波長與量測取樣」，下列哪一項敘述正確？","questionEn":"Which statement about \"Spatial wavelength and sampling\" is correct?","options":["移動量測車把軌道空間波長轉成時間頻率，速度除波長得到激振頻率。","量測車速度提高時仍可永遠沿用原本取樣率","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["A moving inspection vehicle converts track wavelength into temporal frequency through speed divided by wavelength.","The original sampling rate remains sufficient at every increased inspection speed.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"移動量測車把軌道空間波長轉成時間頻率，速度除波長得到激振頻率。 其餘選項是常見誤解。","explanationEn":"A moving inspection vehicle converts track wavelength into temporal frequency through speed divided by wavelength. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b316-v16-34","title":"空間波長與量測取樣：定量估算","titleEn":"Spatial wavelength and sampling: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-33"],"objective":"以數值模型估算「空間波長與量測取樣」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Spatial wavelength and sampling” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：speed=50.5 m/s; wavelength=2 m；計算：nyquist_lower_bound=2*speed/wavelength=50.5 samples/s。敏感度：speed 單獨增加百分之十至 55.55 m/s，其餘固定，結果為 55.55 samples/s。模型邊界：單一最短波長的理想Nyquist下界；實務需留濾波與取樣裕度。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=50.5 m/s; wavelength=2 m; calculation: nyquist_lower_bound=2*speed/wavelength=50.5 samples/s. Sensitivity: speed, increase this input alone by ten percent, to 55.55 m/s, with all other inputs fixed, gives 55.55 samples/s. Model boundary: Ideal Nyquist lower bound for one shortest wavelength; practical filters and sampling need additional margin. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用已知波長的校驗訊號檢查量測鏈，對照獨立里程基準，並在不同車速下比較空間頻譜是否一致。","observationEn":"How to cross-check: Check the chain with a known-wavelength reference, compare an independent distance datum, and inspect whether spatial spectra agree at different vehicle speeds.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：speed=50.5 m/s; wavelength=2 m；計算：nyquist_lower_bound=2*speed/wavelength=50.5 samples/s。敏感度：speed 單獨增加百分之十至 55.55 m/s，其餘固定，結果為 55.55 samples/s。模型邊界：單一最短波長的理想Nyquist下界；實務需留濾波與取樣裕度。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=50.5 m/s; wavelength=2 m; calculation: nyquist_lower_bound=2*speed/wavelength=50.5 samples/s. Sensitivity: speed, increase this input alone by ten percent, to 55.55 m/s, with all other inputs fixed, gives 55.55 samples/s. Model boundary: Ideal Nyquist lower bound for one shortest wavelength; practical filters and sampling need additional margin.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「空間波長與量測取樣」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Spatial wavelength and sampling\", which statement holds?","options":["兩端高程相同就能證明兩點之間沒有差異沉陷","原創假想算例，全部輸入均非本工程操作參數：speed=50.5 m/s; wavelength=2 m。","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Equal endpoint elevations prove there is no differential settlement between them.","Original hypothetical exercise.","A fully restrained rail still expands freely without stress when heated."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：speed=50.5 m/s; wavelength=2 m；計算：nyquist_lower_bound=2*speed/wavelength=50.5 samples/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=50.5 m/s; wavelength=2 m; calculation: nyquist_lower_bound=2*speed/wavelength=50.5 samples/s. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b316-v16-35","title":"空間波長與量測取樣：試驗與驗證","titleEn":"Spatial wavelength and sampling: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「空間波長與量測取樣」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Spatial wavelength and sampling” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用已知波長的校驗訊號檢查量測鏈，對照獨立里程基準，並在不同車速下比較空間頻譜是否一致。 用已知頻率訊號測試整條量測鏈，檢查抗混疊濾波器、時鐘誤差與遺漏樣本。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check the chain with a known-wavelength reference, compare an independent distance datum, and inspect whether spatial spectra agree at different vehicle speeds. Test the complete measurement chain with a known-frequency signal, checking anti-alias filtering, clock error and missing samples. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：把速度提高一成並把最短波長減半，計算取樣率需求，繪出混疊示意後提出抗混疊濾波的頻寬要求。 再以本單元 speed 的對照值重算 nyquist_lower_bound，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase speed by ten percent and halve the shortest wavelength, calculate sampling needs, illustrate aliasing, and specify the required antialias-filter bandwidth. Also recalculate nyquist_lower_bound for the alternative speed value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：不足取樣會把短波缺陷偽裝成長波，里程跳動又會改變重採樣位置；兩者需分別診斷。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Undersampling disguises short-wave defects as long waves, while distance jumps alter resampling positions; the two mechanisms require separate diagnosis. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"用已知波長的校驗訊號檢查量測鏈，對照獨立里程基準，並在不同車速下比較空間頻譜是否一致。 用已知頻率訊號測試整條量測鏈，檢查抗混疊濾波器、時鐘誤差與遺漏樣本。","textEn":"Check the chain with a known-wavelength reference, compare an independent distance datum, and inspect whether spatial spectra agree at different vehicle speeds. Test the complete measurement chain with a known-frequency signal, checking anti-alias filtering, clock error and missing samples.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"把速度提高一成並把最短波長減半，計算取樣率需求，繪出混疊示意後提出抗混疊濾波的頻寬要求。 再以本單元 speed 的對照值重算 nyquist_lower_bound，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase speed by ten percent and halve the shortest wavelength, calculate sampling needs, illustrate aliasing, and specify the required antialias-filter bandwidth. Also recalculate nyquist_lower_bound for the alternative speed value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「空間波長與量測取樣」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Spatial wavelength and sampling\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","空氣體積流率相同就表示任何海拔的散熱質量流率相同","用已知波長的校驗訊號檢查量測鏈，對照獨立里程基準，並在不同車速下比較空間頻譜是否一致。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Equal volumetric airflow guarantees equal cooling mass flow at every altitude.","Check the chain with a known-wavelength reference, compare an independent distance datum, and inspect whether spatial spectra agree at different vehicle speeds."],"answer":2,"explanation":"用已知波長的校驗訊號檢查量測鏈，對照獨立里程基準，並在不同車速下比較空間頻譜是否一致。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check the chain with a known-wavelength reference, compare an independent distance datum, and inspect whether spatial spectra agree at different vehicle speeds. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b316-v16-36","title":"空間波長與量測取樣：失效診斷","titleEn":"Spatial wavelength and sampling: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-35"],"objective":"從症狀倒推「空間波長與量測取樣」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Spatial wavelength and sampling” and propose discriminating checks, corrective actions and prevention.","instruction":"不足取樣會把短波缺陷偽裝成長波，里程跳動又會改變重採樣位置；兩者需分別診斷。 降低取樣率後出現新低頻峰值，應先查混疊而非機械故障。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Undersampling disguises short-wave defects as long waves, while distance jumps alter resampling positions; the two mechanisms require separate diagnosis. A new low-frequency peak after downsampling requires checking aliasing before diagnosing a mechanical fault. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：選擇足以分辨日夜熱循環與列車振動的不同取樣頻率。","observationEn":"Link to the mechanism: Choose different sampling rates for daily thermal cycles and train-induced vibration.","failure":"誤判風險：若相信「量測車速度提高時仍可永遠沿用原本取樣率」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The original sampling rate remains sufficient at every increased inspection speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"不足取樣會把短波缺陷偽裝成長波，里程跳動又會改變重採樣位置；兩者需分別診斷。 降低取樣率後出現新低頻峰值，應先查混疊而非機械故障。","textEn":"Undersampling disguises short-wave defects as long waves, while distance jumps alter resampling positions; the two mechanisms require separate diagnosis. A new low-frequency peak after downsampling requires checking aliasing before diagnosing a mechanical fault.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「空間波長與量測取樣」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Spatial wavelength and sampling\" shows distress, which diagnosis is most reasonable?","options":["不足取樣會把短波缺陷偽裝成長波，里程跳動又會改變重採樣位置；兩者需分別診斷。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["Undersampling disguises short-wave defects as long waves, while distance jumps alter resampling positions; the two mechanisms require separate diagnosis.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"不足取樣會把短波缺陷偽裝成長波，里程跳動又會改變重採樣位置；兩者需分別診斷。 需以量測區分可能原因。","explanationEn":"Undersampling disguises short-wave defects as long waves, while distance jumps alter resampling positions; the two mechanisms require separate diagnosis. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b316-v16-37","title":"可用度與修復時間：機制與系統路徑","titleEn":"Availability and repair time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-36"],"objective":"說明「可用度與修復時間」如何影響青藏鐵路凍土地段的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Availability and repair time” governs forces, deformation, flow or signals in “Qinghai–Tibet Railway permafrost sections”, and map the relevant inputs, transfer paths and boundaries.","instruction":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。這個指標不能替代安全性，因為快速恢復服務可能仍保留危險失效；備品、交通與診斷都會影響實際修復時間。 平均故障間隔和平均修復時間必須使用相同服務邊界；備件等待與到場時間若被排除，數字就不能描述旅客看到的中斷。短期樣本也應報告事件數與觀測時間。 把遠距維修交通時間與實際修復工時分開記錄。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「可用度與修復時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. It does not replace safety: rapidly restoring service may leave a hazardous failure unresolved. Spares, travel and diagnosis all affect actual restoration time. Mean time between failures and mean repair time require a common service boundary. Excluding spare-part waiting or travel time prevents the figure from describing passenger-visible interruption. Short samples should also report event count and observation duration. Record travel time for remote maintenance separately from the hands-on repair duration. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Availability and repair time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mtbf=1212 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9967105 1。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1212 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9967105 1.","failure":"常見誤解：「設備可用度高就表示所有安全風險一定很低」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"High equipment availability necessarily means every safety risk is low.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「可用度與修復時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Availability and repair time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b316-v16-37-k1","title":"可用度與修復時間","titleEn":"Availability and repair time","text":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。這個指標不能替代安全性，因為快速恢復服務可能仍保留危險失效；備品、交通與診斷都會影響實際修復時間。","textEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. It does not replace safety: rapidly restoring service may leave a hazardous failure unresolved.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：設備可用度高就表示所有安全風險一定很低 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: High equipment availability necessarily means every safety risk is low. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「可用度與修復時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Availability and repair time\" is correct?","options":["設備可用度高就表示所有安全風險一定很低","在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。","計算出的凍土融化厚度必定等於路基沉陷量"],"optionsEn":["High equipment availability necessarily means every safety risk is low.","In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time.","Calculated permafrost thaw depth necessarily equals embankment settlement."],"answer":1,"explanation":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。 其餘選項是常見誤解。","explanationEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b316-v16-38","title":"可用度與修復時間：定量估算","titleEn":"Availability and repair time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-37"],"objective":"以數值模型估算「可用度與修復時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Availability and repair time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mtbf=1212 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9967105 1。敏感度：mtbf 單獨增加百分之十至 1333.2 h，其餘固定，結果為 0.9970087 1。模型邊界：兩狀態穩態平均模型；不含計畫維修、共同原因與降級服務品質。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1212 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9967105 1. Sensitivity: mtbf, increase this input alone by ten percent, to 1333.2 h, with all other inputs fixed, gives 0.9970087 1. Model boundary: Two-state steady-state mean model; planned maintenance, common causes and degraded service quality are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。","observationEn":"How to cross-check: Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b316-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mtbf=1212 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9967105 1。敏感度：mtbf 單獨增加百分之十至 1333.2 h，其餘固定，結果為 0.9970087 1。模型邊界：兩狀態穩態平均模型；不含計畫維修、共同原因與降級服務品質。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1212 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9967105 1. Sensitivity: mtbf, increase this input alone by ten percent, to 1333.2 h, with all other inputs fixed, gives 0.9970087 1. Model boundary: Two-state steady-state mean model; planned maintenance, common causes and degraded service quality are excluded.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「可用度與修復時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Availability and repair time\", which statement holds?","options":["排水管截面夠大就不需要檢查入口堵塞及下游水位","兩台儀器量得同樣座標就證明座標絕對正確","原創假想算例，全部輸入均非本工程操作參數：mtbf=1212 h; mttr=4 h。"],"optionsEn":["A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","Matching coordinates from two instruments prove absolute coordinate accuracy.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mtbf=1212 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9967105 1。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1212 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9967105 1. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b316-v16-39","title":"可用度與修復時間：試驗與驗證","titleEn":"Availability and repair time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「可用度與修復時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Availability and repair time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 逐項對照故障開始、服務恢復與維修完成時間，公開排除項，並核對總觀測時數。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Cross-check fault start, service restoration and repair completion for each event, disclose exclusions, and verify total observed hours. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較提高故障間隔與縮短修復時間兩種措施，用同一故障定義重算，並列出可用度之外需要追蹤的危險失效指標。 再以本單元 mtbf 的對照值重算 availability，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare increasing failure interval with reducing repair time under one failure definition, and list hazardous-failure measures that must be tracked separately from availability. Also recalculate availability for the alternative mtbf value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b316-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 逐項對照故障開始、服務恢復與維修完成時間，公開排除項，並核對總觀測時數。","textEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Cross-check fault start, service restoration and repair completion for each event, disclose exclusions, and verify total observed hours.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"比較提高故障間隔與縮短修復時間兩種措施，用同一故障定義重算，並列出可用度之外需要追蹤的危險失效指標。 再以本單元 mtbf 的對照值重算 availability，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare increasing failure interval with reducing repair time under one failure definition, and list hazardous-failure measures that must be tracked separately from availability. Also recalculate availability for the alternative mtbf value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「可用度與修復時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Availability and repair time\"?","options":["將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。","不確定度太難估計，報告中只寫最佳值即可。","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service.","Uncertainty is too hard to estimate, so the report may state only the best value.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":0,"explanation":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b316-v16-40","title":"可用度與修復時間：失效診斷","titleEn":"Availability and repair time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b316-v16-39"],"objective":"從症狀倒推「可用度與修復時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Availability and repair time” and propose discriminating checks, corrective actions and prevention.","instruction":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 修好設備和恢復服務可能不同時，須分別記錄終點。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Equipment repair and service restoration may occur at different times; record both endpoints. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把遠距維修交通時間與實際修復工時分開記錄。","observationEn":"Link to the mechanism: Record travel time for remote maintenance separately from the hands-on repair duration.","failure":"誤判風險：若相信「設備可用度高就表示所有安全風險一定很低」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"High equipment availability necessarily means every safety risk is low.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b316-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 修好設備和恢復服務可能不同時，須分別記錄終點。","textEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Equipment repair and service restoration may occur at different times; record both endpoints.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b316-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「可用度與修復時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Availability and repair time\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。","計算出的凍土融化厚度必定等於路基沉陷量"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Shorter replacement time may not improve availability when spare parts remain unavailable.","Calculated permafrost thaw depth necessarily equals embankment settlement."],"answer":1,"explanation":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 需以量測區分可能原因。","explanationEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v16s-b316-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"curriculumVersion":16,"stepCount":40,"estimatedMinutes":1000,"flowDiagram":"assets/diagrams/v16-b316-zh.svg","flowDiagramEn":"assets/diagrams/v16-b316-en.svg"}};
